import{z as r,x as E,o as p,c as u,q as t,j as s,D as e,d as i,s as o,S as m,b as l}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"Min-p / Typical / η-sampling","description":"","frontmatter":{"title":"Min-p / Typical / η-sampling","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/minp-typical.md","filePath":"llm/minp-typical.md","lastUpdated":1791413859000}'),c={name:"llm/minp-typical.md"};function A(_,a,d,B,h,g){const n=E("Mermaid");return p(),u("div",null,[a[2]||(a[2]=t('<h1 id="min-p-typical-η-sampling" tabindex="-1">Min-p / Typical / η-sampling <a class="header-anchor" href="#min-p-typical-η-sampling" aria-label="Permalink to &quot;Min-p / Typical / η-sampling&quot;">​</a></h1><div class="epigraph"><p>截断采样可以看成对语言模型过度平滑的反向操作：先丢掉过小的原子概率，再在剩下的支撑上归一化，比固定核质量更能跟上每一步的置信度。</p><footer>—— Hewitt, Manning &amp; Liang, Truncation Sampling as Language Model Desmoothing, 2022；Min-p 见 Nguyen et al., 2024</footer></div><p><a href="/llm/sampling-temperature-topp">上一课</a>用温度改熵、top-\\(k\\) 固定集合截断、top-\\(p\\) 按累计质量自适应截断。缺口是：nucleus 的核宽不看峰有多尖——高峰时可能只剩两三个 token，平坦时为凑满 \\(p\\) 会吞进碎块。开放生成里分布有时几乎确定、有时在近义续写之间摊平，需要随当前分布自适应的地板。Hewitt 等人的 \\(\\varepsilon\\) / \\(\\eta\\)、Nguyen 等人的 min-\\(p\\) 同属截断族；按熵距离取核见 <a href="/llm/locally-typical">Locally Typical Sampling</a>。本课写相对峰高与随熵浮动的截断。不重推温度与 nucleus 的定义。后课重复惩罚默认已经分清「改支撑」与「改已出现 token 的分」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言模型在词表上给出的 \\(p(\\cdot\\mid x_{\\lt t})\\) 被训练成处处为正。长尾里有大量语法尚可、语义无关的 token，它们的对数概率并不低到能被温度单独压死。Holtzman 等人已经说明：贪心与束会退化成重复，从未经截断的分布里采样又会抽到长尾胡话。Nucleus 的对策是取最小集合使其概率和达到 \\(p\\)，再归一化。这一集合的基数随分布形状变：高峰时可能只剩两三个 token，平坦时可能上百。它不保证「比最大项小两个数量级的质量被切掉」——若头部有十个近乎等概率的词，核会把它们全留下，这是合理的；若头部一个 \\(0.92\\)、其余碎成几千份，核仍可能为凑满 \\(p\\) 而吞进许多碎块。</p><p>绝对地板更直白：概率低于 \\(\\varepsilon\\) 的 token 直接丢掉。困难在于 \\(\\varepsilon\\) 是跨步共享的标量。模型自信时 \\(p_{\\max}\\) 接近 \\(1\\)，\\(\\varepsilon=10^{-4}\\) 几乎只切真正的噪声；犹豫时 \\(p_{\\max}\\) 只有 \\(0.15\\)，同一个 \\(\\varepsilon\\) 可能把所有候选取消，或几乎切不到。需要一种随当前分布自适应的地板，而不是再调一个与 nucleus 平行的全局 \\(p\\)。</p><p><span class="marginnote">直觉类比：固定 \\(\\varepsilon\\) 是「一刀切的及格线」，不管这次考试多难；min-\\(p\\) 把及格线改成「冠军得分的固定比例」——冠军跑出 0.9 时及格线水涨船高，冠军只有 0.2 时及格线跟着下调。这样每一步淘汰多少人由当步的竞争格局决定，而不是全局常数。</span></p><h3 id="平滑、温度与截断不是同一旋钮" tabindex="-1">平滑、温度与截断不是同一旋钮 <a class="header-anchor" href="#平滑、温度与截断不是同一旋钮" aria-label="Permalink to &quot;平滑、温度与截断不是同一旋钮&quot;">​</a></h3><p>温度 \\(T\\) 把 \\(\\mathrm{softmax}(z/T)\\) 的锋利程度整体拉开或压平，不删除支撑。Nucleus 与 top-\\(k\\) 删除支撑再归一化，改变的是样本空间。Hewitt 等人的论点是：训练目标与标签平滑、词表过大，都会把质量摊到不该出现的 token 上；截断是在推理时把这层平滑Undo 掉。\\(\\varepsilon\\) 与 \\(\\eta\\) 针对原子概率，\\(\\min\\)-\\(p\\) 针对相对峰高。把温度调到 \\(1.2\\) 再叠一层固定 \\(p=0.9\\) 的核，解决不了「这一步很尖、下一步很平」的逐步差异。自适应地板要回答的正是这个逐步差异。</p><p><span class="marginnote">Nucleus 不是 typical 的别名。Nucleus 按概率从大到小累加；typical 按与熵的距离排序。\\(\\eta\\) 与 min-\\(p\\) 都不排序累加，只设一条水平线。三条线切出来的集合可以相交，但包含关系不成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记当前步 \\(p_i=p(v_i\\mid x_{\\lt t})\\)，\\(p_{\\max}=\\max_i p_i\\)，熵 \\(H=-\\sum_i p_i\\log p_i\\)（约定 \\(0\\log 0=0\\)）。</p><p>\\(\\varepsilon\\)-sampling 的支撑是 \\(\\{i:p_i\\ge\\varepsilon\\}\\)，细节与去平滑解释见 <a href="/llm/epsilon-sampling">Epsilon sampling</a>。\\(\\eta\\)-sampling 把地板改成</p> \\[\\eta=\\min\\bigl(\\varepsilon,\\,\\sqrt{\\varepsilon}\\,\\mathrm{e}^{-H}\\bigr), \\]<p>再取 \\(\\{i:p_i\\ge\\eta\\}\\)。熵高时 \\(\\mathrm{e}^{-H}\\) 小，地板下降，避免把平坦分布切空；熵低时地板被 \\(\\varepsilon\\) 卡住，避免高峰旁的碎质量混进来。实现上先算熵与 \\(\\eta\\)，再掩码、再归一化、再采样。</p><p>Min-\\(p\\) 不显式用熵。超参 \\(p_{\\mathrm{base}}\\in(0,1)\\) 给出相对地板</p> \\[\\tau = p_{\\mathrm{base}}\\cdot p_{\\max}, \\]<p>支撑为 \\(\\{i:p_i\\ge\\tau\\}\\)。\\(p_{\\max}=0.9\\)、\\(p_{\\mathrm{base}}=0.1\\) 时 \\(\\tau=0.09\\)，只留与冠军同量级的候选项；\\(p_{\\max}=0.2\\) 时 \\(\\tau=0.02\\)，低置信度步留下更宽的核。Nguyen 等人强调它在高温下仍能保持连贯：温度把分布拉平后，\\(p_{\\max}\\) 下降，门槛跟着下降，创造空间不被固定 nucleus 一次切死。</p><p><span class="marginnote">数字实例（\\(\\eta\\) 的地板随熵浮动）：若模型把质量均匀摊在约 10 万个 token 上，\\(H=\\ln(100000)\\approx 11.5\\)，\\(\\mathrm{e}^{-H}\\approx 10^{-5}\\)；取 \\(\\varepsilon=10^{-4}\\)，则 \\(\\eta=\\min(10^{-4},\\,10^{-2}\\times 10^{-5})=10^{-7}\\)——地板几乎归零，平坦分布不会被切空。反过来熵很低时 \\(\\mathrm{e}^{-H}\\) 接近 1，地板被 \\(\\varepsilon\\) 卡住，长尾进不来。</span></p><h3 id="与-nucleus、top-的切法对照" tabindex="-1">与 nucleus、top-\\(k\\) 的切法对照 <a class="header-anchor" href="#与-nucleus、top-的切法对照" aria-label="Permalink to &quot;与 nucleus、top-$k$ 的切法对照&quot;">​</a></h3><p>Nucleus 排序后累加到质量 \\(p\\)，集合大小由质量预算决定。Top-\\(k\\) 集合大小固定，不管峰有多尖。Min-\\(p\\) 与 \\(\\eta\\) 的集合大小都是数据依赖的，但判据不同：前者比的是「相对冠军」，后者比的是「相对 \\(\\varepsilon\\) 与平均信息量」。高峰且长尾细碎时，min-\\(p\\) 通常比 nucleus 更狠；多峰近平局时，min-\\(p\\) 的 \\(\\tau\\) 低，接近少截断，nucleus 仍按 \\(p\\) 收核。Top-\\(a\\) 用 \\(p_{\\max}\\) 的平方做地板，形状更陡，见 <a href="/llm/top-a-sampling">Top-a</a>。</p><p>工程上这些截断都是 logits 处理器：在 softmax 之后或等价地对低于门槛的 logit 置 \\(-\\infty\\)。与温度的顺序要固定：先温度再截断，或先截断再温度，对应两种分布，评测必须写明。与 <a href="/llm/repetition-penalty">重复惩罚</a> 叠用时，惩罚先改 logit，再进入 \\(p_{\\max}\\) 或熵的估计，否则门槛看到的不是采样真正使用的分布。</p>',22)),(p(),s(m,null,{default:e(()=>[o(n,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22logits%22%5D%20--%3E%20T%5B%22%E6%B8%A9%E5%BA%A6%20T%22%5D%0A%20%20T%20--%3E%20P%5B%22softmax%20%E5%BE%97%20p%22%5D%0A%20%20P%20--%3E%20C%7B%22%E6%88%AA%E6%96%AD%E8%A7%84%E5%88%99%22%7D%0A%20%20C%20--%3E%7C%22%E7%B4%AF%E8%AE%A1%E8%B4%A8%E9%87%8F%20%E2%89%A5%20p%22%7C%20NUC%5B%22nucleus%22%5D%0A%20%20C%20--%3E%7C%22p_i%20%E2%89%A5%20%CE%B5%22%7C%20EPS%5B%22%CE%B5-sampling%22%5D%0A%20%20C%20--%3E%7C%22p_i%20%E2%89%A5%20%CE%B7(H%2C%CE%B5)%22%7C%20ETA%5B%22%CE%B7-sampling%22%5D%0A%20%20C%20--%3E%7C%22p_i%20%E2%89%A5%20p_base%20%C2%B7%20p_max%22%7C%20MINP%5B%22min-p%22%5D%0A%20%20NUC%20--%3E%20R%5B%22%E5%BD%92%E4%B8%80%E5%8C%96%E5%86%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20EPS%20--%3E%20R%0A%20%20ETA%20--%3E%20R%0A%20%20MINP%20--%3E%20R%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[i("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"去平滑的直觉是：模型把本该是零的概率做成很小的正数，截断把这些正数打回零。\\(\\varepsilon\\) 是与位置无关的绝对噪声地板。\\(\\eta\\) 承认「噪声」应随这一步有多不确定而变：高熵意味着模型认为许多 token 都合理，地板应当降低，以免误杀；低熵意味着模型已经把质量集中，地板应当至少保持 \\(\\varepsilon\\)，以免长尾回流。指数 \\(\\mathrm{e}^{-H}\\) 来自把平均概率尺度 \\(\\mathrm{e}^{-H}\\) 与 \\(\\varepsilon\\) 做几何折中，Hewitt 文中的 \\(\\sqrt{\\varepsilon}\\) 是一条经实验固定的配合系数，不是信息论定理里的唯一选择。",-1)),(p(),s(m,null,{default:e(()=>[o(n,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E5%BD%93%E5%89%8D%E6%AD%A5%E7%9A%84%E5%80%99%E9%80%89%E5%88%86%E5%B8%83%22%5D%20--%3E%20Q%7B%22%E5%86%A0%E5%86%9B%20p_max%20%E6%9C%89%E5%A4%9A%E5%B0%96%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%87%AA%E4%BF%A1%EF%BC%9Ap_max%20%3D%200.9%22%7C%20H%5B%22%CF%84%20%3D%200.1%20%C3%97%200.9%20%3D%200.09%22%5D%0A%20%20H%20--%3E%20H2%5B%22%E5%8F%AA%E7%95%99%E4%B8%8E%E5%86%A0%E5%86%9B%E5%90%8C%E9%87%8F%E7%BA%A7%E7%9A%84%E5%B0%91%E6%95%B0%E5%80%99%E9%80%89%EF%BC%8C%E8%BF%91%E8%B4%AA%E5%BF%83%22%5D%0A%20%20Q%20--%3E%7C%22%E7%8A%B9%E8%B1%AB%EF%BC%9Ap_max%20%3D%200.2%22%7C%20L%5B%22%CF%84%20%3D%200.1%20%C3%97%200.2%20%3D%200.02%22%5D%0A%20%20L%20--%3E%20L2%5B%22%E9%97%A8%E6%A7%9B%E8%87%AA%E5%8A%A8%E6%94%BE%E5%AE%BD%EF%BC%8C%E6%A0%B8%E5%8F%98%E5%AE%BD%EF%BC%8C%E4%BF%9D%E7%95%99%E6%8E%A2%E7%B4%A2%22%5D%0A%20%20H2%20--%3E%20N%5B%22%E9%87%8D%E6%96%B0%E5%BD%92%E4%B8%80%E5%8C%96%E5%90%8E%E9%87%87%E6%A0%B7%22%5D%0A%20%20L2%20--%3E%20N%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>Min-\\(p\\) 用 \\(p_{\\max}\\) 当置信度代理。尖峰时 \\(p_{\\max}\\) 大，相对门槛高，行为接近「几乎贪心但允许近义词」；平坦时 \\(p_{\\max}\\) 小，相对门槛低，行为接近温度采样。它不需要额外的熵扫描，只多一次求最大——在词表 \\(10^5\\) 量级上与 softmax 相比可忽略。与 typical 的差别在于：typical 会丢掉过尖的头部（信息量低于熵太多的那些「太可预测」的 token），min-\\(p\\) 与 \\(\\eta\\) 都保留头部，只砍尾巴。若任务要避免套话，应看 Meister 的局部典型集，而不是把 min-\\(p\\) 调得更小。</p><h3 id="高温与自适应地板" tabindex="-1">高温与自适应地板 <a class="header-anchor" href="#高温与自适应地板" aria-label="Permalink to &quot;高温与自适应地板&quot;">​</a></h3><p>固定 nucleus 在 \\(T\\gt 1\\) 时常常要么仍然过窄（核质量不够覆盖被温度摊开的头部），要么为了覆盖而把 \\(p\\) 调到接近 \\(1\\)，等于放弃截断。Min-\\(p\\) 的卖点是同一 \\(p_{\\mathrm{base}}\\) 在高温下自动放宽。这不是免费的多样性：放宽之后长尾会回来，胡话率仍随 \\(T\\) 上升，只是上升得比「高温 + 固定 \\(p=0.9\\)」更可控。\\(\\eta\\) 同样在高熵时放宽，但驱动信号是熵而不是 \\(p_{\\max}\\)。双峰分布可以有中等熵、却有很高的 \\(p_{\\max}\\)（若一峰略高），此时 min-\\(p\\) 与 \\(\\eta\\) 的支撑会分叉——这是调参时要对着具体模型看的现象，不是实现 bug。</p><p><span class="marginnote">\\(p_{\\mathrm{base}}\\) 不是 nucleus 的 \\(p\\)。\\(0.1\\) 的 min-\\(p\\) 在 \\(p_{\\max}=0.8\\) 时门槛是 \\(0.08\\)，可能只留数个 token；nucleus \\(p=0.1\\) 几乎总是过窄。不要把社区博客里的「0.1」跨算法抄参数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自适应截断改变的是每步支撑，不提供序列级的重复控制，也不提供结构约束。停用与文法仍要另接 <a href="/llm/stop-sequences">stop sequences</a> 与约束解码。投机解码若要保持目标分布，草稿与目标必须使用同一套截断；只在目标上做 min-\\(p\\)、草稿上做 nucleus，接受率与无损证明都会坏，见 <a href="/llm/speculative-sampling">投机采样</a>。</p><p>\\(\\eta\\) 依赖熵，需要对有效支撑求和，数值上应在截断前用原来的 \\(p\\) 算 \\(H\\)，不要用已经掩码的分布再算一遍门槛，否则门槛与定义不一致。极小概率的 token 对熵贡献弱，但 \\(\\log\\) 要用稳定实现。词表含大量从未出现的字节级碎片时，\\(\\varepsilon\\) 与 min-\\(p\\) 通常比 top-\\(k\\) 更稳，因为 \\(k\\) 很难同时适合中文单字与英文 BPE 碎片。</p><p>服务默认值不要三套齐开。Min-\\(p\\) 与 nucleus 同时生效时，最终支撑是交集，有效核可能被切空，实现必须处理「支撑为空则回退到 \\(\\arg\\max\\)」这类退化。评测开放生成质量时，把 \\(T\\)、min-\\(p\\)、\\(p\\)、\\(\\varepsilon\\) 写成协议的一部分，否则「同一个模型更会讲故事」无法复现。</p><p><span class="marginnote">常见误区：把 min-\\(p\\) 与 nucleus 同时打开当「双保险」。两个过滤器取交集后，nucleus 的质量预算和 min-\\(p\\) 的相对地板会互相不知情地收窄，极端时把候选切到只剩一两个还自以为保留了多样性。先用一种截断，看分布再决定要不要第二种。</span></p><p><span class="marginnote">出处以 Hewitt et al. 2022 的 \\(\\varepsilon\\)/\\(\\eta\\) 与 Nguyen et al. 2024 的 min-\\(p\\) 为准。Hugging Face <code>typical_p</code> 实现的是 Meister 的局部典型采样，不要在本篇参数表里把 <code>typical_p</code> 当成 \\(\\eta\\)。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nucleus 按累计质量切核；\\(\\varepsilon\\) 按绝对概率切尾；\\(\\eta\\) 让地板随熵变；min-\\(p\\) 让地板随 \\(p_{\\max}\\) 变。</li><li>四者都是逐步截断再归一化，目标是去掉过度平滑的长尾，而不是近似 MAP。</li><li>\\(\\eta=\\min(\\varepsilon,\\sqrt{\\varepsilon}\\,\\mathrm{e}^{-H})\\) 在高熵时放宽、低熵时至少保持 \\(\\varepsilon\\)。</li><li>Min-\\(p\\) 用 \\(\\tau=p_{\\mathrm{base}}p_{\\max}\\)，高温下门槛随峰值下降，比固定核质量更跟得上置信度。</li><li>Typical 按与熵的距离取核，可能丢掉过可预测的头部，与只砍尾巴的 min-\\(p\\)/\\(\\eta\\) 不是同一集合。</li><li>与温度、重复惩罚、投机校验叠用时，必须以同一分布估计门槛，避免空支撑与无损证明失效。</li><li>出处：Hewitt et al., <em>Truncation Sampling as Language Model Desmoothing</em>, 2022；Nguyen et al., <em>Turning Up the Heat: Min-P Sampling</em>, 2024。Nucleus 对照见 Holtzman et al., ICLR 2020。</li></ul>',12))])}const D=r(c,[["render",A]]);export{x as __pageData,D as default};
